UPDATE templates
SET description = 'Sechs Abschnitte: TL;DR, Entscheidungen, Themen aus dem Gespräch statt fester Liste, Aufgaben als Tabelle mit Wer und Bis, offene Fragen, Zitate. Für Beratungs- und Projektgespräche, in denen hinterher zählt, wer was bis wann macht.',
    sections_json = '[{"title": "TL;DR", "description": "Die drei bis fünf wichtigsten Punkte, Entscheidungen und Aufgaben zuerst, für jemanden mit dreißig Sekunden."}, {"title": "Entscheidungen", "description": "Was tatsächlich entschieden wurde, ein Stichpunkt je Entscheidung. Eine Entscheidung braucht jemanden, der sie getroffen und ausgesprochen hat. Eine Absicht, ein Plan, ein Wunsch, eine Erwartung oder ein Vorschlag, dem nur niemand widersprochen hat, ist KEINE Entscheidung; er gehört zu den Aufgaben oder nirgendwo hin."}, {"title": "Themen", "description": "Schreib KEINE Überschrift, die wörtlich „Themen“ heisst. Bau diesen Teil aus dem Gespräch selbst: eine eigene Überschrift je Thema, das wirklich besprochen wurde, benannt nach diesem Thema. Folge den echten Themen und ihrer Gewichtung, nie einer festen Liste; überspring, was nicht vorkam. Fass zusammen, was zusammengehört: lieber vier bis sechs tragende Überschriften als ein Dutzend feine. Eine Randnotiz bekommt keine eigene Überschrift, sondern einen Stichpunkt unter dem Thema, zu dem sie gehört. Eine Entscheidung, die oben schon steht, wird hier nicht noch einmal ausgeschrieben; hier steht nur, was zu ihr geführt hat. Jeder Inhalt gehört unter eine dieser Überschriften, nie ein Textblock ohne Überschrift darüber. Darunter Stichpunkte, nie Fliesstext: dieser Teil wird überflogen, nicht gelesen. Drei zusammenhängende Sätze in einem Absatz sind falsch, auch wenn jeder Satz darin stimmt -- zerleg sie in ihre einzelnen Punkte."}, {"title": "Aufgaben", "description": "Als Markdown-TABELLE mit genau diesen Spalten:\n\n| Aufgabe | Wer | Bis |\n|---|---|---|\n\nEine Zeile je Aufgabe. Schreib nie ein Pipe-Zeichen in eine Tabellenzelle, das bricht die Tabelle; formulier um oder ersetz es durch ein Komma."}, {"title": "Offene Fragen", "description": "Was angesprochen, aber nicht geklärt wurde, dazu jede Stelle, an der das Transkript widersprüchlich oder unverständlich war. Ein Stichpunkt je Frage."}, {"title": "Zitate", "description": "Ganz am Schluss: bis zu drei WÖRTLICHE Aussagen, Wort für Wort, nie umformuliert oder geglättet, die einen Kernpunkt des Gesprächs treffen, jeweils mit dem Sprecher, aber nur bei eindeutiger Zuordnung. Ist die Formulierung im Transkript verstümmelt, lass das Zitat weg, statt es zu reparieren."}]'
WHERE id = 'mitschnitt-kompakt'
  AND title = 'Mitschnitt Kompakt'
  AND description = 'Sieben Abschnitte: TL;DR, Entscheidungen, Themen aus dem Gespräch statt fester Liste, Aufgaben als Tabelle mit Wer und Bis, offene Fragen, Zahlen und Namen zur Gegenprüfung, Zitate. Für Beratungs- und Projektgespräche, in denen hinterher zählt, wer was bis wann macht.'
  AND sections_json = '[{"title": "TL;DR", "description": "Die drei bis fünf wichtigsten Punkte, Entscheidungen und Aufgaben zuerst, für jemanden mit dreißig Sekunden."}, {"title": "Entscheidungen", "description": "Was tatsächlich entschieden wurde, ein Stichpunkt je Entscheidung. Eine Entscheidung braucht jemanden, der sie getroffen und ausgesprochen hat. Eine Absicht, ein Plan, ein Wunsch, eine Erwartung oder ein Vorschlag, dem nur niemand widersprochen hat, ist KEINE Entscheidung; er gehört zu den Aufgaben oder nirgendwo hin."}, {"title": "Themen", "description": "Schreib KEINE Überschrift, die wörtlich „Themen“ heisst. Bau diesen Teil aus dem Gespräch selbst: eine eigene Überschrift je Thema, das wirklich besprochen wurde, benannt nach diesem Thema. Folge den echten Themen und ihrer Gewichtung, nie einer festen Liste; überspring, was nicht vorkam. Fass zusammen, was zusammengehört: lieber vier bis sechs tragende Überschriften als ein Dutzend feine. Eine Randnotiz bekommt keine eigene Überschrift, sondern einen Stichpunkt unter dem Thema, zu dem sie gehört. Eine Entscheidung, die oben schon steht, wird hier nicht noch einmal ausgeschrieben; hier steht nur, was zu ihr geführt hat. Jeder Inhalt gehört unter eine dieser Überschriften, nie ein Textblock ohne Überschrift darüber. Darunter Stichpunkte, nie Fliesstext: dieser Teil wird überflogen, nicht gelesen. Drei zusammenhängende Sätze in einem Absatz sind falsch, auch wenn jeder Satz darin stimmt -- zerleg sie in ihre einzelnen Punkte."}, {"title": "Aufgaben", "description": "Als Markdown-TABELLE mit genau diesen Spalten:\n\n| Aufgabe | Wer | Bis |\n|---|---|---|\n\nEine Zeile je Aufgabe. Schreib nie ein Pipe-Zeichen in eine Tabellenzelle, das bricht die Tabelle; formulier um oder ersetz es durch ein Komma."}, {"title": "Offene Fragen", "description": "Was angesprochen, aber nicht geklärt wurde, dazu jede Stelle, an der das Transkript widersprüchlich oder unverständlich war. Ein Stichpunkt je Frage."}, {"title": "Zahlen und Namen zur Gegenprüfung", "description": "Alle Zahlen, Beträge, Termine und Eigennamen aus dem Gespräch, so wie sie im Transkript stehen, als kurze Liste. Sie dienen dem Gegenprüfen, weil sich die Transkription verhören kann; nichts ergänzen, nichts runden. Schreibt das Transkript denselben Namen verschieden, nenn die Varianten nebeneinander, statt dich für eine zu entscheiden."}, {"title": "Zitate", "description": "Ganz am Schluss: bis zu drei WÖRTLICHE Aussagen, Wort für Wort, nie umformuliert oder geglättet, die einen Kernpunkt des Gesprächs treffen, jeweils mit dem Sprecher, aber nur bei eindeutiger Zuordnung. Ist die Formulierung im Transkript verstümmelt, lass das Zitat weg, statt es zu reparieren."}]';


